import {predict,engineer} from './engine.mjs';
const $=s=>document.querySelector(s),form=$('#spec-form'),names={xgboost:'XGBoost',linear:'Linear regression',ridge:'Ridge regression',forest:'Random forest'};
let models={},options,examples,selected=null,active='xgboost',last=null,band='all',ready=false,busy=false;
const fmt=n=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function data(path){const r=await fetch('data/'+path);if(!r.ok)throw new Error('Could not load '+path);return r.json();}
function setOptions(field,values,value){const el=form.elements[field];el.replaceChildren(...[...new Set([...values,...(value?[String(value)]:[])])].map(v=>new Option(v,v)));if(value!=null)el.value=String(value);}
function updateModels(value){const brand=form.elements.brand.value;setOptions('model',options.brand_models.filter(x=>x.brand===brand).map(x=>x.model).sort(),value);}
function current(){const d=Object.fromEntries(new FormData(form));for(const k of ['ram_gb','storage_gb','screen_in'])d[k]=Number(d[k]);return d;}
function summary(){const d=engineer(current());$('#cpu-family').textContent='Processor family: '+d.cpu;$('#summaries').textContent=`CPU generation / series: ${d.cpu_generation_or_series} · CPU suffix: ${d.cpu_suffix} · GPU brand: ${d.gpu_brand} · GPU family: ${d.gpu_family}`;}
function matches(d){return selected&&Object.entries(selected.input).every(([k,v])=>String(d[k])===String(v));}
function banner(){const same=matches(current());$('#selected-example').hidden=!selected;if(selected)$('#selected-example').textContent=same?`Test example #${selected.id} loaded. Its actual price will be revealed with the prediction.`:'You changed this example. Its original price will not be used as a comparison.';}
function fill(example,track=true){selected=track?example:null;const d=example.input;setOptions('brand',options.options.brand,d.brand);updateModels(d.model);for(const [k,v] of Object.entries(d)){const el=form.elements[k];if(!el)continue;if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===String(v)))el.add(new Option(v,v));el.value=v;}summary();banner();last=null;$('#result-content').innerHTML='<div class="empty-state"><div class="empty-graphic">↗ <span>···</span></div><p>Specs loaded. Let’s see what the models think.</p><small>Press Predict price to calculate all four predictions.</small></div>';$('#result-badge').textContent='READY WHEN YOU ARE';renderExamples();}
function renderExamples(){const sorted=[...examples].sort((a,b)=>a.actual-b.actual);const ids=band==='low'?[15,45,75,100]:band==='high'?[335,375,405,425]:[35,155,310,410];const chosen=ids.map(i=>sorted[i]);$('#example-list').innerHTML=chosen.map(ex=>{const d=ex.input,isHigh=ex.actual>=sorted[324].actual,isLow=ex.actual<=sorted[107].actual;return `<article class="example-card ${selected?.id===ex.id?'selected':''}"><div class="card-top"><span class="tag ${isHigh?'high-tag':''}">${isHigh?'HIGH-PRICE QUARTER':isLow?'LOW-PRICE QUARTER':'MID-RANGE'}</span><span class="id">#${ex.id}</span></div><h3>${esc(d.brand)} ${esc(d.model)}</h3><div class="spec-chips"><span>${esc(d.cpu_model)}</span><span>${d.ram_gb} GB RAM</span><span>${d.storage_gb} GB ${esc(d.storage_type)}</span></div><p class="card-gpu">${esc(d.gpu)} · ${d.screen_in}″ · ${esc(d.status)}</p><div class="card-bottom"><div class="price"><small>ACTUAL LISTED PRICE</small><strong>${fmt(ex.actual)}</strong><em>units</em></div><button type="button" class="load-button" data-example="${ex.id}">${selected?.id===ex.id?'Loaded':'Load specs'} <span>↗</span></button></div></article>`;}).join('');}
function renderResult(){if(!last)return;const p=last.predictions[active],actual=last.actual,diff=actual==null?null:p-actual;$('#result-badge').textContent=actual==null?'CUSTOM CONFIGURATION':'TEST EXAMPLE #'+last.id;$('#result-content').innerHTML=`<div class="prediction-layout reveal"><span class="result-label">${names[active].toUpperCase()} / PREDICTED PRICE</span><div class="prediction-number">${fmt(p)}<small>source price units</small></div>${actual!=null?`<div class="compare-grid"><div class="compare-box"><span>ACTUAL LISTED PRICE</span><strong>${fmt(actual)}</strong></div><div class="compare-box error-box"><span>ABSOLUTE ERROR</span><strong>${fmt(Math.abs(diff))}</strong><small> · ${Math.abs(diff/actual*100).toFixed(1)}%</small></div></div><div class="difference-bar"><span>${diff>=0?'OVER':'UNDER'} BY ${fmt(Math.abs(diff))}</span><div class="track"><i style="width:${Math.min(Math.abs(diff/actual)*100,100)}%"></i></div><span>${Math.abs(diff/actual*100).toFixed(1)}%</span></div>`:'<p class="result-context">No verified actual price for this configuration. Select an unchanged test example to compare a prediction with its real listed price.</p>'}<table class="all-models"><thead><tr><th>MODEL</th><th>PREDICTION</th>${actual!=null?'<th>ABSOLUTE ERROR</th>':''}</tr></thead><tbody>${Object.entries(names).map(([key,label])=>`<tr class="${key===active?'selected-row':''}"><td>${label}</td><td>${fmt(last.predictions[key])}</td>${actual!=null?`<td>${fmt(Math.abs(last.predictions[key]-actual))}</td>`:''}</tr>`).join('')}</tbody></table><p class="result-context">${actual!=null?'Actual price is used only after prediction to calculate the error. It is never passed to the models.':'All four estimates use the same laptop specifications.'} These are estimates, not current market valuations or individual confidence intervals.</p></div>`;}
form.addEventListener('submit',async e=>{e.preventDefault();if(!ready||busy||!form.reportValidity())return;busy=true;const button=$('#predict');button.disabled=true;button.classList.add('busy');button.firstElementChild.textContent='Preparing specs → running four models…';$('#error').hidden=true;try{const input=current();await new Promise(resolve=>setTimeout(resolve,450));const predictions=Object.fromEntries(Object.entries(models).map(([key,m])=>[key,predict(m,input)]));if(Object.values(predictions).some(v=>!Number.isFinite(v)||v<=0))throw new Error('This configuration could not produce a valid prediction. Please check the inputs.');const same=matches(input);last={predictions,actual:same?selected.actual:null,id:same?selected.id:null};renderResult();$('#results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}catch(err){$('#error').textContent=err.message;$('#error').hidden=false;}finally{busy=false;button.disabled=false;button.classList.remove('busy');button.firstElementChild.textContent='Predict price';}});
form.addEventListener('change',e=>{if(e.target.name==='brand')updateModels();if(e.target.name==='cpu_model'){const pair=options.cpu_pairs.find(x=>x.cpu_model===form.elements.cpu_model.value);if(pair)form.elements.cpu.value=pair.cpu;}summary();banner();if(last){last=null;$('#result-content').innerHTML='<div class="empty-state"><p>Specs changed. Predict again to update the results.</p></div>';}});
document.addEventListener('click',e=>{const ex=e.target.closest('[data-example]');if(ex){fill(examples.find(x=>x.id===Number(ex.dataset.example)));if(innerWidth<721)form.scrollIntoView({behavior:'smooth',block:'start'});}const filter=e.target.closest('[data-band]');if(filter){band=filter.dataset.band;document.querySelectorAll('[data-band]').forEach(b=>b.classList.toggle('active',b===filter));renderExamples();}const tab=e.target.closest('[data-model]');if(tab){active=tab.dataset.model;document.querySelectorAll('[data-model]').forEach(b=>{b.classList.toggle('active',b===tab);b.setAttribute('aria-selected',String(b===tab));});renderResult();}});
$('#detail-toggle').addEventListener('click',()=>{const box=$('#summaries');box.hidden=!box.hidden;$('#detail-toggle').textContent=box.hidden?'+':'−';$('#detail-toggle').setAttribute('aria-expanded',String(!box.hidden));});
$('#reset').addEventListener('click',()=>{if(!ready)return;fill([...examples].sort((a,b)=>a.actual-b.actual)[155],false);});
try{[options,examples]=await Promise.all([data('options.json'),data('examples.json')]);for(const [key,values] of Object.entries(options.options))if(form.elements[key])setOptions(key,values);fill([...examples].sort((a,b)=>a.actual-b.actual)[155],false);models=Object.fromEntries(await Promise.all(Object.keys(names).map(async name=>[name,await data(name+'.json')])));ready=true;$('#predict').disabled=false;$('#predict').firstElementChild.textContent='Predict price';}catch(err){$('#error').textContent='The model files could not load. Please reload the page. '+err.message;$('#error').hidden=false;$('#predict').firstElementChild.textContent='Models unavailable';}
